// Settings: schema-driven. UI is generated from SCHEMA, values persist to
// localStorage, and every value is reachable as settings.get('group.key').

const STORAGE_KEY = 'neonstrike.settings.v1';

export const SCHEMA = {
  graphics: {
    label: 'Graphics',
    items: {
      preset: { label: 'Quality Preset', type: 'enum', options: ['potato', 'balanced', 'high', 'ultra', 'custom'], default: 'balanced' },
      resolutionScale: { label: 'Resolution Scale', type: 'range', min: 0.25, max: 1.5, step: 0.05, default: 0.75 },
      fov: { label: 'Field of View', type: 'range', min: 60, max: 120, step: 1, default: 95 },
      rayBounces: { label: 'RT Reflection Bounces', type: 'range', min: 0, max: 3, step: 1, default: 1 },
      shadows: { label: 'RT Shadows', type: 'enum', options: ['off', 'hard', 'soft'], default: 'soft' },
      softShadowSamples: { label: 'Soft Shadow Samples', type: 'range', min: 2, max: 8, step: 1, default: 4 },
      ambientOcclusion: { label: 'RT Ambient Occlusion', type: 'enum', options: ['off', 'low', 'high'], default: 'low' },
      fog: { label: 'Distance Fog', type: 'bool', default: true },
      emissivePulse: { label: 'Neon Pulse Animation', type: 'bool', default: true },
      frameCap: { label: 'Frame Cap', type: 'enum', options: ['off', '30', '60', '120', '144'], default: 'off' },
      showFps: { label: 'Show FPS Counter', type: 'bool', default: true },
    },
  },
  audio: {
    label: 'Audio',
    items: {
      master: { label: 'Master Volume', type: 'range', min: 0, max: 100, step: 1, default: 80 },
      sfx: { label: 'Effects Volume', type: 'range', min: 0, max: 100, step: 1, default: 100 },
      ui: { label: 'UI Volume', type: 'range', min: 0, max: 100, step: 1, default: 80 },
      ambient: { label: 'Ambient Volume', type: 'range', min: 0, max: 100, step: 1, default: 50 },
      hitsound: { label: 'Hit Confirmation Sound', type: 'bool', default: true },
    },
  },
  controls: {
    label: 'Controls',
    items: {
      sensitivity: { label: 'Mouse Sensitivity', type: 'range', min: 0.1, max: 5, step: 0.05, default: 1.0 },
      adsScale: { label: 'Scoped Sensitivity Scale', type: 'range', min: 0.2, max: 1.5, step: 0.05, default: 0.8 },
      invertY: { label: 'Invert Y Axis', type: 'bool', default: false },
      crouchToggle: { label: 'Toggle Crouch', type: 'bool', default: false },
      viewBobbing: { label: 'View Bobbing', type: 'bool', default: true },
    },
  },
  crosshair: {
    label: 'Crosshair',
    items: {
      style: { label: 'Style', type: 'enum', options: ['cross', 'dot', 'circle', 'cross+dot'], default: 'cross' },
      size: { label: 'Size', type: 'range', min: 2, max: 30, step: 1, default: 9 },
      gap: { label: 'Gap', type: 'range', min: 0, max: 16, step: 1, default: 4 },
      thickness: { label: 'Thickness', type: 'range', min: 1, max: 6, step: 1, default: 2 },
      color: { label: 'Color', type: 'color', default: '#3dffc8' },
      outline: { label: 'Outline', type: 'bool', default: true },
      dynamic: { label: 'Dynamic (expands with spread)', type: 'bool', default: true },
    },
  },
  game: {
    label: 'Game',
    items: {
      botCount: { label: 'Bot Count', type: 'range', min: 1, max: 8, step: 1, default: 4 },
      difficulty: { label: 'Bot Difficulty', type: 'enum', options: ['easy', 'normal', 'hard', 'elite'], default: 'normal' },
      roundTime: { label: 'Round Time (s)', type: 'range', min: 60, max: 300, step: 5, default: 115 },
      radar: { label: 'Radar', type: 'bool', default: true },
      killFeed: { label: 'Kill Feed', type: 'bool', default: true },
      damageNumbers: { label: 'Damage Numbers', type: 'bool', default: true },
      viewmodel: { label: 'Show Viewmodel', type: 'bool', default: true },
    },
  },
};

export const PRESETS = {
  potato: { resolutionScale: 0.4, rayBounces: 0, shadows: 'off', softShadowSamples: 2, ambientOcclusion: 'off', fog: false, emissivePulse: false },
  balanced: { resolutionScale: 0.75, rayBounces: 1, shadows: 'hard', softShadowSamples: 2, ambientOcclusion: 'low', fog: true, emissivePulse: true },
  high: { resolutionScale: 1.0, rayBounces: 2, shadows: 'soft', softShadowSamples: 4, ambientOcclusion: 'low', fog: true, emissivePulse: true },
  ultra: { resolutionScale: 1.25, rayBounces: 3, shadows: 'soft', softShadowSamples: 8, ambientOcclusion: 'high', fog: true, emissivePulse: true },
};

export class Settings {
  constructor() {
    this.values = {};
    this.listeners = [];
    for (const [g, group] of Object.entries(SCHEMA)) {
      this.values[g] = {};
      for (const [k, item] of Object.entries(group.items)) {
        this.values[g][k] = item.default;
      }
    }
    this._load();
  }

  _load() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return;
      const saved = JSON.parse(raw);
      for (const g of Object.keys(this.values)) {
        if (!saved[g]) continue;
        for (const k of Object.keys(this.values[g])) {
          if (k in saved[g]) this.values[g][k] = saved[g][k];
        }
      }
    } catch (e) { /* corrupted save: keep defaults */ }
  }

  save() {
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(this.values)); } catch (e) { /* private mode */ }
  }

  get(path) {
    const [g, k] = path.split('.');
    return this.values[g][k];
  }

  set(path, val, opts = {}) {
    const [g, k] = path.split('.');
    const item = SCHEMA[g].items[k];
    if (item.type === 'range') {
      val = Math.max(item.min, Math.min(item.max, Number(val)));
    } else if (item.type === 'bool') {
      val = !!val;
    }
    this.values[g][k] = val;
    // applying a preset writes graphics keys; manual graphics edits flip preset to custom
    if (g === 'graphics' && k !== 'preset' && k !== 'fov' && k !== 'frameCap' && k !== 'showFps' && !opts.fromPreset) {
      this.values.graphics.preset = 'custom';
    }
    if (g === 'graphics' && k === 'preset' && PRESETS[val]) {
      for (const [pk, pv] of Object.entries(PRESETS[val])) {
        this.values.graphics[pk] = pv;
      }
    }
    this.save();
    for (const fn of this.listeners) fn(path, val);
  }

  onChange(fn) { this.listeners.push(fn); }

  resetDefaults() {
    for (const [g, group] of Object.entries(SCHEMA)) {
      for (const [k, item] of Object.entries(group.items)) {
        this.values[g][k] = item.default;
      }
    }
    this.save();
    for (const fn of this.listeners) fn('*', null);
  }

  // Renderer-facing snapshot
  gfx() {
    const g = this.values.graphics;
    return {
      rayBounces: Math.round(g.rayBounces),
      shadowMode: { off: 0, hard: 1, soft: 2 }[g.shadows],
      softShadowSamples: Math.round(g.softShadowSamples),
      aoMode: { off: 0, low: 1, high: 2 }[g.ambientOcclusion],
      fog: g.fog,
      emissivePulse: g.emissivePulse,
      resolutionScale: g.resolutionScale,
      fov: (g.fov * Math.PI) / 180,
      frameCap: g.frameCap === 'off' ? 0 : Number(g.frameCap),
      showFps: g.showFps,
    };
  }
}

// ---------- UI ----------
export function buildSettingsUI(container, settings, onClose) {
  container.innerHTML = '';
  const tabs = document.createElement('div');
  tabs.className = 'settings-tabs';
  const body = document.createElement('div');
  body.className = 'settings-body';
  container.appendChild(tabs);
  container.appendChild(body);

  const groups = Object.keys(SCHEMA);
  let active = groups[0];

  function renderBody() {
    body.innerHTML = '';
    const group = SCHEMA[active];
    for (const [k, item] of Object.entries(group.items)) {
      const row = document.createElement('div');
      row.className = 'settings-row';
      const label = document.createElement('label');
      label.textContent = item.label;
      row.appendChild(label);
      const path = `${active}.${k}`;
      const cur = settings.get(path);

      let input;
      if (item.type === 'range') {
        input = document.createElement('input');
        input.type = 'range';
        input.min = item.min; input.max = item.max; input.step = item.step;
        input.value = cur;
        const valSpan = document.createElement('span');
        valSpan.className = 'settings-val';
        valSpan.textContent = cur;
        input.addEventListener('input', () => {
          settings.set(path, Number(input.value));
          valSpan.textContent = settings.get(path);
        });
        row.appendChild(input);
        row.appendChild(valSpan);
      } else if (item.type === 'bool') {
        input = document.createElement('input');
        input.type = 'checkbox';
        input.checked = cur;
        input.addEventListener('change', () => settings.set(path, input.checked));
        row.appendChild(input);
      } else if (item.type === 'enum') {
        input = document.createElement('select');
        for (const opt of item.options) {
          const o = document.createElement('option');
          o.value = opt; o.textContent = opt;
          if (opt === cur) o.selected = true;
          input.appendChild(o);
        }
        input.addEventListener('change', () => {
          settings.set(path, input.value);
          if (path === 'graphics.preset') renderBody(); // preset rewrites sliders
        });
        row.appendChild(input);
      } else if (item.type === 'color') {
        input = document.createElement('input');
        input.type = 'color';
        input.value = cur;
        input.addEventListener('input', () => settings.set(path, input.value));
        row.appendChild(input);
      }
      input.dataset.setting = path;
      body.appendChild(row);
    }
    if (active === 'crosshair') {
      const prev = document.createElement('div');
      prev.className = 'crosshair-preview';
      prev.innerHTML = '<div class="ch-preview-stage"><div id="ch-preview"></div></div>';
      body.appendChild(prev);
      drawCrosshairPreview(settings);
    }
  }

  for (const g of groups) {
    const btn = document.createElement('button');
    btn.className = 'tab-btn';
    btn.textContent = SCHEMA[g].label;
    btn.dataset.tab = g;
    btn.addEventListener('click', () => {
      active = g;
      tabs.querySelectorAll('.tab-btn').forEach(b => b.classList.toggle('active', b.dataset.tab === g));
      renderBody();
    });
    if (g === active) btn.classList.add('active');
    tabs.appendChild(btn);
  }

  const footer = document.createElement('div');
  footer.className = 'settings-footer';
  const reset = document.createElement('button');
  reset.className = 'btn-secondary';
  reset.textContent = 'Reset Defaults';
  reset.addEventListener('click', () => { settings.resetDefaults(); renderBody(); });
  const close = document.createElement('button');
  close.className = 'btn-primary';
  close.textContent = 'Done';
  close.addEventListener('click', onClose);
  footer.appendChild(reset);
  footer.appendChild(close);
  container.appendChild(footer);

  settings.onChange((path) => {
    if (path.startsWith('crosshair') || path === '*') drawCrosshairPreview(settings);
  });

  renderBody();
}

export function crosshairCSS(settings, spreadPx = 0) {
  const s = {
    style: settings.get('crosshair.style'),
    size: settings.get('crosshair.size'),
    gap: settings.get('crosshair.gap') + (settings.get('crosshair.dynamic') ? spreadPx : 0),
    th: settings.get('crosshair.thickness'),
    color: settings.get('crosshair.color'),
    outline: settings.get('crosshair.outline'),
  };
  return s;
}

export function renderCrosshair(el, s) {
  el.innerHTML = '';
  const mk = (w, h, x, y) => {
    const d = document.createElement('div');
    d.style.cssText = `position:absolute;background:${s.color};width:${w}px;height:${h}px;` +
      `left:${x}px;top:${y}px;${s.outline ? 'box-shadow:0 0 0 1px rgba(0,0,0,0.8);' : ''}`;
    el.appendChild(d);
  };
  const { size, gap, th } = s;
  if (s.style === 'cross' || s.style === 'cross+dot') {
    mk(size, th, -gap - size, -th / 2);
    mk(size, th, gap, -th / 2);
    mk(th, size, -th / 2, -gap - size);
    mk(th, size, -th / 2, gap);
  }
  if (s.style === 'dot' || s.style === 'cross+dot') {
    mk(th + 1, th + 1, -(th + 1) / 2, -(th + 1) / 2);
  }
  if (s.style === 'circle') {
    const d = document.createElement('div');
    d.style.cssText = `position:absolute;border:${th}px solid ${s.color};border-radius:50%;` +
      `width:${size * 2}px;height:${size * 2}px;left:${-size - th}px;top:${-size - th}px;` +
      (s.outline ? 'box-shadow:0 0 0 1px rgba(0,0,0,0.8), inset 0 0 0 1px rgba(0,0,0,0.8);' : '');
    el.appendChild(d);
  }
}

function drawCrosshairPreview(settings) {
  const el = document.getElementById('ch-preview');
  if (!el) return;
  renderCrosshair(el, crosshairCSS(settings));
}
